// C++17 — só aceita tipos inteiros
template <typename T,
          typename = std::enable_if_t<std::is_integral_v<T>>>
T add(T a, T b) { return a + b; }

// Erro em chamada com float: cascata de 300 linhas

#include <concepts>

template <std::integral T>
T add(T a, T b) { return a + b; }

// Erro amigável: "note: because 'std::integral<double>' is not satisfied"

template <typename T>
concept Printable = requires(T t, std::ostream& os) {
    { os << t } -> std::same_as<std::ostream&>;
};

template <Printable T>
void log(const T& value) {
    std::cout << "[log] " << value << '\n';
}

// 1. Como prefixo de typename
template <std::integral T> void f(T);

// 2. Cláusula requires posicionada
template <typename T>
    requires std::integral<T>
void g(T);

// 3. Trailing requires
template <typename T>
void h(T) requires std::integral<T>;

// 4. Abbreviated
void k(std::integral auto x);

void format(std::integral auto x) {
    std::print("{:d}\n", x);
}

void format(std::floating_point auto x) {
    std::print("{:.2f}\n", x);
}

void format(std::ranges::range auto const& r) {
    for (auto const& e : r) format(e);
}

template <typename T>
std::string show(const T& v) {
    if constexpr (std::integral<T>)        return std::to_string(v);
    else if constexpr (std::is_enum_v<T>)  return std::to_string(int(v));
    else                                    return std::format("{}", v);
}
